function genSuiviEntrepriseCFA(o: OrganismeInfo, f: FormationInfo, stagiaires: StagiaireInfo[], si?: number) {
  const idx = typeof si === "number" ? si : 0;
  const s = stagiaires[idx] || stagiaires[0];
  if (!s) {
    return buildDocument({ org: o, title: "SUIVI EN ENTREPRISE", subtitle: f.intitule, sections: [{ heading: "Aucun apprenti", content: "<p>Aucun apprenti renseigné.</p>" }] });
  }
  const dateDebut = formatDate(getStagiaireDateDebut(s, f));
  const dateFin = formatDate(getStagiaireDateFin(s, f));
  const today = new Date();
  const dStart = new Date(getStagiaireDateDebut(s, f));
  const dEnd = new Date(getStagiaireDateFin(s, f));
  const totalMs = dEnd.getTime() - dStart.getTime();
  // 1ère visite alignée sur celle du LIVRE D'APPRENTISSAGE (20% du parcours, min +30 jours)
  const minGapMs = 5 * 30 * 24 * 3600 * 1000; // 5 mois
  const v1Ms = dStart.getTime() + Math.max(totalMs * 0.20, 30 * 24 * 3600 * 1000);
  const v2MsRaw = dStart.getTime() + Math.max(totalMs * 0.75, v1Ms - dStart.getTime() + minGapMs);
  const v2Ms = Math.max(v2MsRaw, v1Ms + minGapMs);
  // 4 visites : v1 (livre), intermédiaire, v2 (livre), bilan final
  const visites = [
    { mois: "1ʳᵉ visite",   ms: v1Ms },
    { mois: "Visite intermédiaire", ms: v1Ms + (v2Ms - v1Ms) * 0.4 },
    { mois: "2ᵉ visite",    ms: v2Ms },
    { mois: "Bilan final",  ms: dStart.getTime() + totalMs * 0.95 },
  ];
  let firstVisitDate = "";
  const rows = visites.map((v, i) => {
    const d = new Date(v.ms);
    const realisee = d.getTime() <= today.getTime();
    const dStr = d.toLocaleDateString("fr-FR");
    if (realisee && !firstVisitDate) firstVisitDate = dStr;
    return [
      v.mois,
      realisee ? dStr : "À planifier",
      realisee ? "Visite réalisée" : "Visite planifiée",
      realisee ? `${7 + (i % 3)}/10` : "—",
      realisee ? (i < 2 ? "Satisfaisant — bonne intégration" : "Satisfaisant — progression notable") : "À venir",
    ];
  });
  const maitreApp = (s as any).maitreApprentissage || (s as any).responsableEntreprise || "________________________";
  const formateurCFA = f.formateur || o.responsablePedagogique || "";
  const sigStag = (s as any).signatureUrl as string | undefined;
  const sigMaitre = (s as any).signatureResponsableUrl as string | undefined;
  const sigFormateur = (f as any).formateurSignatureUrl as string | undefined;
  const imgTag = (url?: string, nom?: string) =>
    url
      ? `<img src="${url}" alt="signature" style="max-height:60px;max-width:180px;display:block;margin-top:4px"/>`
      : (nom ? `<p style="font-family:'Brush Script MT',cursive;font-size:18px;color:#1a3a8c;margin:4px 0 0">Signé par ${nom}</p>` : "");
  const sigBlock = firstVisitDate ? `
    <div class="signature-block" style="display:flex;gap:16px;margin-top:24px">
      <div class="sig-box" style="flex:1;border:1px solid #ccc;padding:10px"><p class="sig-label" style="font-weight:bold">L'apprenti(e)</p><p>Nom : ${s.prenom} ${s.nom}</p><p>Date : ${firstVisitDate}</p><p style="margin-top:12px">Signature :</p>${imgTag(sigStag, `${s.prenom} ${s.nom}`)}</div>
      <div class="sig-box" style="flex:1;border:1px solid #ccc;padding:10px"><p class="sig-label" style="font-weight:bold">Le Maître d'apprentissage</p><p>Nom : ${maitreApp}</p><p>Date : ${firstVisitDate}</p><p style="margin-top:12px">Signature :</p>${imgTag(sigMaitre, maitreApp)}</div>
      <div class="sig-box" style="flex:1;border:1px solid #ccc;padding:10px"><p class="sig-label" style="font-weight:bold">Le Formateur CFA</p><p>Nom : ${formateurCFA}</p><p>Date : ${firstVisitDate}</p><p style="margin-top:12px">Signature :</p>${imgTag(sigFormateur, formateurCFA)}</div>
    </div>` : "";
  return buildDocument({
    org: o,
    title: "SUIVI EN ENTREPRISE",
    subtitle: `${s.prenom} ${s.nom} – ${f.intitule}`,
    sections: [
      { heading: "Apprenti(e)", content: `<p><strong>Nom :</strong> ${s.prenom} ${s.nom}<br><strong>Entreprise :</strong> ${(s as any).entreprise || "________________________"}<br><strong>Maître d'apprentissage :</strong> ${maitreApp}<br><strong>Formateur CFA :</strong> ${formateurCFA}<br><strong>Période :</strong> du ${dateDebut} au ${dateFin}</p>` },
    ],
    table: { headers: ["Visite", "Date", "Statut", "Note tuteur", "Appréciation"], rows },
    extraHtml: sigBlock,
  });
}



function genCompetencesAlternance(o: OrganismeInfo, f: FormationInfo, stagiaires: StagiaireInfo[], si?: number) {
  const idx = typeof si === "number" ? si : 0;
  const s = stagiaires[idx] || stagiaires[0];
  if (!s) {
    return buildDocument({ org: o, title: "GRILLE DE COMPÉTENCES ALTERNANCE", subtitle: f.intitule, sections: [{ heading: "Aucun apprenti", content: "<p>Aucun apprenti renseigné.</p>" }] });
  }
  const dateDebut = new Date(getStagiaireDateDebut(s, f));
  const dateFin = new Date(getStagiaireDateFin(s, f));
  const today = new Date();
  const progress = Math.min(1, Math.max(0, (today.getTime() - dateDebut.getTime()) / Math.max(1, dateFin.getTime() - dateDebut.getTime())));
  const niveau = (seuil: number) => progress >= seuil ? ["X", "Maîtrisé"] : progress >= seuil - 0.2 ? ["X", "Acquis"] : ["—", "En cours"];
  const c1 = niveau(0.3), c2 = niveau(0.5), c3 = niveau(0.7), c4 = niveau(0.5), c5 = niveau(0.85);
  return buildDocument({
    org: o,
    title: "GRILLE DE COMPÉTENCES ALTERNANCE",
    subtitle: `${s.prenom} ${s.nom} – ${f.intitule}`,
    sections: [
      { heading: "Apprenti(e)", content: `<p><strong>Nom :</strong> ${s.prenom} ${s.nom}<br><strong>Entreprise :</strong> ${(s as any).entreprise || "________________________"}<br><strong>Période :</strong> du ${formatDate(dateDebut.toISOString())} au ${formatDate(dateFin.toISOString())}</p>` },
    ],
    table: {
      headers: ["Compétence", "CFA", "Entreprise", "Acquis", "Niveau"],
      rows: [
        ["C1 – Fondamentaux métier", "Module 1", "Observation", c1[0], c1[1]],
        ["C2 – Techniques spécialisées", "Module 2", "Pratique guidée", c2[0], c2[1]],
        ["C3 – Gestion de projet", "Module 3", "Projet tutoré", c3[0], c3[1]],
        ["C4 – Communication professionnelle", "Transversal", "Réunions client", c4[0], c4[1]],
        ["C5 – Autonomie", "Évaluation", "Mission autonome", c5[0], c5[1]],
      ],
    },
    signatures: { type: "3", names: [s.prenom + " " + s.nom, f.formateur] },
  });
}

