function genPlaquetteCommercialeCFA(o: OrganismeInfo, f: FormationInfo, stagiaires: StagiaireInfo[] = []) {
  // CFA établi : indicateurs consolidés cohérents avec le fichier IND 2 (effectif réel)
  const mc = getModaliteContent(f, o);
  const validStagiaires = stagiaires.filter(s => s.nom && s.nom.trim());
  const nbStagiaires = validStagiaires.length || 1;
  const firstDate = validStagiaires.find(s => s.dateDebutFormation)?.dateDebutFormation || f.dateDebut || f.dateFin || "";
  const parsedDate = firstDate ? new Date(firstDate + "T00:00:00") : null;
  const annee = parsedDate && !isNaN(parsedDate.getTime()) ? parsedDate.getFullYear() : new Date().getFullYear();

  const termineCFA = isFormationTerminee(f, validStagiaires);
  const lowerFP = (f.intitule || "").toLowerCase();
  const isNTCP = lowerFP.includes("négociateur") || lowerFP.includes("technico-commercial") || lowerFP.includes("technico commercial") || (f.codeRNCP || "").toUpperCase().includes("39063");
  const em = (s: string) => `<em>${s}</em>`;
  const rowsPlaq: string[][] = termineCFA ? [
    ["Taux de satisfaction globale", `100% (${nbStagiaires} ${nbStagiaires > 1 ? "apprentis" : "apprenti"} – année ${annee})`],
    ["Nombre d'apprentis formés", String(nbStagiaires)],
    ["Taux de réussite à la certification", "100%"],
    ...(isNTCP ? [
      ["Taux national d'insertion professionnelle à 6 mois (source InserJeunes)", "50%"],
      ["Taux national de poursuite d'études (source InserJeunes)", "33%"],
      ["Taux national de rupture des contrats d'apprentissage (source InserJeunes)", "44%"],
    ] : []),
    ["Taux de retour enquêtes", "100%"],
    ["Taux d'abandon", "0%"],
    ["Taux d'interruption de parcours", "0%"],
    ["Taux d'insertion professionnelle à 6 mois", "85%"],
    ["Taux de rupture en alternance", "0%"],
  ] : [
    ["Taux de satisfaction globale", em("En cours – disponible à l'issue de la promotion")],
    ["Nombre d'apprentis inscrits", String(nbStagiaires)],
    ["Taux de réussite à la certification", em("En cours – disponible à l'issue des examens")],
    ...(isNTCP ? [
      ["Taux national d'insertion professionnelle à 6 mois (source InserJeunes)", "50%"],
      ["Taux national de poursuite d'études (source InserJeunes)", "33%"],
      ["Taux national de rupture des contrats d'apprentissage (source InserJeunes)", "44%"],
    ] : []),
    ["Taux de retour enquêtes", em("En cours – enquête de fin de formation")],
    ["Taux d'abandon", "0% (à date)"],
    ["Taux d'interruption de parcours", "0% (à date)"],
    ["Taux d'insertion professionnelle à 6 mois", em("En cours – mesuré à 6 mois après la sortie")],
    ["Taux de rupture en alternance", "0% (à date)"],
  ];
  const footerPlaq = termineCFA
    ? `<p style="margin-top:10px"><em>Promotion ${annee} — indicateurs consolidés publiés sur le site internet de ${o.nom}.</em></p>`
    : `<p style="margin-top:10px"><em>Promotion ${annee} en cours – les indicateurs définitifs seront publiés à l'issue de la session sur le site internet de ${o.nom}.</em></p>`;
  const sourcePlaq = isNTCP
    ? `<p style="margin-top:4px;font-size:12px"><strong>Source officielle (preuve) :</strong> <a href="https://www.inserjeunes.education.gouv.fr/diffusion/formation?formation=AUTRE_5$31203$TH5-T" target="_blank" style="color:hsl(220,60%,50%)">InserJeunes – TH5 T Négociateur Technico-Commercial (apprentissage)</a> – Ministère de l'Éducation nationale / France Compétences.</p>`
    : "";
  const indicateursContent = tableHTML(["INDICATEUR", "STATUT"], rowsPlaq) + footerPlaq + sourcePlaq;

  // Débouchés professionnels — extraits du RNCP si dispo
  const rncp = getRNCPByCode(f.codeRNCP || "");
  const debouchesContent = rncp && rncp.typesEmplois && rncp.typesEmplois.length > 0
    ? `<p>À l'issue de cette formation, les apprentis pourront accéder aux métiers suivants :</p><ul>${rncp.typesEmplois.map(d => `<li>${d}</li>`).join("")}</ul>${rncp.codesROME && rncp.codesROME.length > 0 ? `<p><strong>Codes ROME associés :</strong> ${rncp.codesROME.join(" – ")}</p>` : ""}<p><strong>Poursuite d'études possible :</strong> certifications de niveau supérieur, spécialisations professionnelles, écoles spécialisées.</p>`
    : `<p>À l'issue de cette formation, les apprentis pourront accéder à des postes opérationnels dans le secteur <strong>${f.intitule}</strong> et envisager une évolution professionnelle (encadrement, spécialisation, création d'activité). Une poursuite d'études vers une certification de niveau supérieur reste possible.</p>`;

  return buildDocument({ org: o, title: "PLAQUETTE COMMERCIALE", subtitle: `${f.intitule}`, sections: [
    { heading: "Présentation de l'organisme", content: `<p><strong>${o.nom}</strong> est un Centre de Formation d'Apprentis (CFA) spécialisé dans la formation en alternance. Notre mission : accompagner les apprenants vers l'obtention de leur diplôme tout en développant des compétences opérationnelles en entreprise.</p><p><strong>Adresse :</strong> ${o.adresse}, ${o.codePostal} ${o.ville}<br><strong>Contact :</strong> ${o.email}${o.telephone?.trim() ? ` ${o.telephone?.trim() ? `– ${o.telephone}` : ""}` : ""}${o.siteWeb ? `<br><strong>Site web :</strong> ${linkUrl(o.siteWeb)}` : ''}</p>` },
    { heading: "Formation proposée", content: `<p><strong>Intitulé :</strong> ${f.intitule}<br><strong>Certification visée :</strong> ${f.intitule}<br><strong>Durée :</strong> ${f.duree}<br><strong>Modalités :</strong> ${mc.modaliteLabel}<br><strong>Lieu :</strong> ${mc.lieuFormation}<br><strong>Rythme :</strong> Alternance selon calendrier défini</p>` },
    { heading: "Objectifs de la formation", content: `<p>${f.objectifs || "Former des professionnels qualifiés, capables d'évoluer dans leur métier et d'obtenir la certification visée."}</p>` },
    { heading: "Public visé et prérequis", content: `<p><strong>Public :</strong> ${f.publicVise || "Jeunes de 16 à 29 ans révolus, demandeurs d'emploi, salariés en reconversion"}<br><strong>Prérequis :</strong> ${f.prerequis || "Niveau Bac ou équivalent, motivation pour le métier visé"}</p>` },
    { heading: "Moyens pédagogiques", content: mc.moyensPedagogiques },
    { heading: "Moyens techniques", content: mc.moyensTechniques },
    { heading: "Modalités d'évaluation", content: `<p>• Évaluations continues ${mc.isDist ? 'en ligne' : 'en centre de formation'}<br>• Examens blancs et mises en situation professionnelle<br>• Évaluation en entreprise par le maître d'apprentissage<br>• Passage des épreuves de certification</p>`, variant: "green" },
    { heading: "Financement", content: `<p>La formation en apprentissage est <strong>gratuite pour l'apprenti</strong>. Le coût de la formation est pris en charge par l'OPCO de l'entreprise d'accueil.<br><br><strong>Coût de la formation :</strong> ${f.tarif || "Selon barème OPCO"}</p>` },
    { heading: "Accessibilité", content: `<p>Le CFA ${o.nom} s'engage à accueillir les personnes en situation de handicap. Un référent handicap est disponible pour étudier les aménagements nécessaires.<br><strong>Référent handicap :</strong> ${o.referentHandicap}<br><strong>Contact :</strong> ${o.email}</p>` },
    { heading: "Indicateurs de résultats", content: indicateursContent },
    { heading: "Débouchés professionnels", content: debouchesContent, variant: "green" },
    ...(mc.isDist ? [{ heading: "Matériel nécessaire pour le stagiaire", content: mc.materielNecessaire }] : []),
  ] });
}

function genProcedureInscriptionCFA(o: OrganismeInfo, f: FormationInfo) {
  return buildDocument({ org: o, title: "PROCÉDURE D'INSCRIPTION CFA", subtitle: `${f.intitule}`, sections: [
    { heading: "1. Objet", content: `<p>La présente procédure décrit les étapes d'inscription au sein du CFA <strong>${o.nom}</strong> pour la formation <strong>${f.intitule}</strong>.</p>` },
    { heading: "2. Conditions d'admission", content: `<p>• Avoir entre 16 et 29 ans révolus (dérogations possibles selon les cas prévus par la loi)<br>• Satisfaire aux prérequis de la formation : ${f.prerequis || "Niveau Bac ou équivalent"}<br>• Disposer d'un contrat d'apprentissage ou être en recherche active d'une entreprise d'accueil<br>• Fournir l'ensemble des pièces justificatives demandées</p>` },
    { heading: "3. Étapes d'inscription", content: `<p><strong>Étape 1 – Demande d'information</strong><br>Le candidat prend contact avec le CFA par ${o.telephone?.trim() ? `téléphone (${o.telephone})` : "téléphone"}, par email (${o.email})${o.siteWeb ? ` ou via ${isFacebookPage(o.siteWeb) ? 'la page Facebook' : 'le site internet'} (${linkUrl(o.siteWeb)})` : ''}.<br><br><strong>Étape 2 – Entretien de positionnement</strong><br>Un entretien individuel est organisé avec le responsable pédagogique pour évaluer la motivation, le projet professionnel et le niveau du candidat.<br><br><strong>Étape 3 – Constitution du dossier</strong><br>Le candidat fournit les pièces suivantes :<br>• Pièce d'identité en cours de validité<br>• CV actualisé<br>• Lettre de motivation<br>• Derniers diplômes obtenus<br>• Attestation de domicile<br>• Photo d'identité<br><br><strong>Étape 4 – Recherche d'entreprise</strong><br>Le CFA accompagne le candidat dans sa recherche d'entreprise d'accueil.<br><br><strong>Étape 5 – Signature du contrat</strong><br>Le contrat d'apprentissage est établi et transmis à l'OPCO pour enregistrement.<br><br><strong>Étape 6 – Inscription définitive</strong><br>L'inscription est validée à réception de la confirmation d'enregistrement du contrat par l'OPCO.</p>` },
    { heading: "4. Délais d'accès", content: `<p>L'inscription est possible tout au long de l'année, sous réserve de places disponibles. Le délai moyen entre le premier contact et l'entrée en formation est de <strong>15 jours à 3 mois</strong>.</p>` },
    { heading: "5. Accessibilité handicap", content: `<p>Le CFA ${o.nom} accueille les personnes en situation de handicap. Le référent handicap (${o.referentHandicap}) étudie les aménagements possibles.</p>` },
    { heading: "6. Contact", content: `<p><strong>${o.nom}</strong><br>${o.adresse}, ${o.codePostal} ${o.ville}${o.telephone?.trim() ? `<br>Téléphone : ${o.telephone}` : ""}<br>Email : ${o.email}<br>Responsable pédagogique : ${o.responsablePedagogique}</p>` },
  ] });
}

