function aiPackPlaceholder(o: OrganismeInfo, f: FormationInfo, title: string, s?: StagiaireInfo): string {
  const stag = s ? ` – ${s.prenom} ${s.nom}` : "";
  return buildDocument({
    org: o, title: `${title}${stag}`, subtitle: f.intitule, formation: f, showFormationInfo: true,
    extraHtml: `<div class="section section-yellow" style="padding:20px;border-left:4px solid #f59e0b">
      <h3>Pack d'évaluation IA non encore généré</h3>
      <p>Pour personnaliser ce document avec un contenu 100% adapté à la formation <strong>« ${f.intitule} »</strong>,
      cliquez sur le bouton <strong>« Générer évaluations IA »</strong> dans le module (OPCO, EDOF EY ou Qualiopi).</p>
      <p>L'IA produira alors un pack cohérent : 10 QCM positionnement début, 10 QCM positionnement fin,
      1 exercice intermédiaire (4 questions), 1 évaluation finale (5 exercices).</p>
    </div>`,
  });
}

function genAITestPositionnement(o: OrganismeInfo, f: FormationInfo, stagiaires: StagiaireInfo[], si: number, mode: "debut" | "fin", isOpco: boolean = false): string {
  const pack: AIEvalPack | null = getCachedPack(f);
  const s = stagiaires[si] || stagiaires[0];
  const title = mode === "debut" ? "TEST DE POSITIONNEMENT — DÉBUT DE FORMATION" : "TEST DE POSITIONNEMENT — FIN DE FORMATION";
  if (!pack) return aiPackPlaceholder(o, f, title, s);

  const qcm = mode === "debut" ? pack.qcmDebut : pack.qcmFin;

  // Si test de FIN et formation non terminée pour ce stagiaire → trame vierge
  const stagFini = isStagiaireFormationTerminee(s, f);
  const renderEmpty = mode === "fin" && !stagFini;

  // Cible de score (DÉBUT) en fonction du nombre d'heures (et jours) du stagiaire
  let targetCorrect: number | undefined;
  if (mode === "debut" && !isOpco) {
    const stagDuree = getStagiaireDuree(s, f);
    let hours = 0;
    const m1 = /(\d+)\s*[hH]/.exec(stagDuree) || /(\d+)\s*[hH]/.exec(f.duree || "") || /(\d+)\s*[hH]/.exec(f.intitule || "");
    if (m1) hours = parseInt(m1[1], 10);
    const days = getStagiaireDays(s, f).length;
    if (!hours) hours = days * 7;
    const seedBase = (s?.prenom || "").length * 13 + (s?.nom || "").length * 17 + si * 7;
    const v2 = seedBase % 2;       // 0 ou 1
    const v3 = seedBase % 3;       // 0, 1 ou 2

    // Cas particulier : 12 jours + 40h → toujours 4
    if (days >= 12 && hours >= 35 && hours <= 45) {
      targetCorrect = 4;
    } else if (hours <= 15) {
      targetCorrect = 6 + v2;                     // 6 ou 7
    } else if (hours <= 17) {
      targetCorrect = 5 + v3;                     // 5, 6 ou 7
    } else if (hours <= 20) {
      targetCorrect = 5 + v3;                     // 5, 6 ou 7
    } else if (hours <= 30) {
      targetCorrect = 4 + v3;                     // 4, 5 ou 6
    } else if (hours <= 40) {
      targetCorrect = 4 + v2;                     // 4 ou 5
    } else if (hours <= 65) {
      targetCorrect = 3 + v3;                     // 3, 4 ou 5
    } else {
      targetCorrect = 3;                          // > 65h : très débutant
    }
  }


  const answers = renderEmpty ? [] : answersForQCM(qcm, si, s, mode, isOpco, targetCorrect);
  let correct = 0;
  const isDebut = mode === "debut";
  // Détection GOTRM : injection de commentaires stagiaires humanisés dans la cellule "Réponse"
  const tTitle = (f.intitule || "").toLowerCase();
  const isGOTRM = tTitle.includes("gotrm") || tTitle.includes("gestionnaire des opérations de transport") || tTitle.includes("exploitant transport") || tTitle.includes("tp-01329") || tTitle.includes("rncp40990") || (f.codeRNCP || "").toUpperCase().includes("40990");
  const isWord = tTitle.includes("initiation word") || (tTitle.includes("word") && !tTitle.includes("pack office") && !tTitle.includes("bureautique"));
  const gotrmSeed = isGOTRM
    ? ((s?.prenom || "").length * 131 + (s?.nom || "").length * 197 + si * 41 + (isDebut ? 3 : 11))
    : 0;
  const wordSeed = isWord
    ? ((s?.prenom || "").length * 131 + (s?.nom || "").length * 197 + si * 41 + (isDebut ? 5 : 13))
    : 0;
  const isCrea = isCreationEntrepriseFormation(f.intitule || "");
  const creaSeed = isCrea
    ? ((s?.prenom || "").length * 131 + (s?.nom || "").length * 197 + si * 41 + (isDebut ? 7 : 17))
    : 0;
  const rows = qcm.map((q, qi) => {
    const optionsCell = q.options.map((opt, oi) => `${String.fromCharCode(65 + oi)}) ${opt}`).join("<br>");
    if (renderEmpty) {
      return [
        `Q${qi + 1}`,
        q.question,
        optionsCell,
        "À compléter",
        "—",
      ];
    }
    const chosen = answers[qi];
    const ok = chosen === q.correctIndex;
    if (ok) correct++;
    const chosenLabel = `${String.fromCharCode(65 + chosen)}) ${q.options[chosen]}`;
    const humanCommentText = isGOTRM
      ? pickGOTRMComment(mode as "debut" | "fin", qi, gotrmSeed)
      : isWord
        ? pickWordComment(mode as "debut" | "fin", qi, wordSeed)
        : isCrea
          ? pickCreaComment(mode as "debut" | "fin", qi, creaSeed)
          : "";
    const humanNote = humanCommentText
      ? `<br><em style="color:#475569;font-size:0.92em">« ${humanCommentText} »</em>`
      : "";
    if (isDebut) {
      return [
        `Q${qi + 1}`,
        q.question,
        optionsCell,
        chosenLabel + humanNote,
        `${String.fromCharCode(65 + q.correctIndex)}) ${q.options[q.correctIndex]}`,
        ok ? "Correct" : "Incorrect",
      ];
    }
    return [
      `Q${qi + 1}`,
      q.question,
      chosenLabel + humanNote,
      `${String.fromCharCode(65 + q.correctIndex)}) ${q.options[q.correctIndex]}`,
      ok ? "Correct" : "Incorrect",
    ];
  });


  const dateDebutSession = formatDate(getStagiaireDateDebut(s, f));
  const dateFinSession = formatDate(getStagiaireDateFin(s, f));

  let extra = `<h2>${title}</h2>`;
  extra += `<p><strong>Stagiaire :</strong> ${s.civilite ? s.civilite + " " : ""}${s.prenom} ${s.nom}<br>
    <strong>Formation :</strong> ${f.intitule}<br>
    <strong>Session :</strong> du ${dateDebutSession} au ${dateFinSession}<br>
    <strong>Date :</strong> ${renderEmpty ? "À compléter en fin de formation" : formatDate(mode === "debut" ? getStagiaireDateDebut(s, f) : getStagiaireDateFin(s, f))}<br>
    <strong>Nombre de questions :</strong> ${qcm.length} — <strong>Durée :</strong> 30 minutes — <strong>Barème :</strong> 1 pt / réponse</p>`;

  if (renderEmpty) {
    extra += `<div class="section" style="background:#fef3c7;border-left:3px solid #f59e0b;padding:10px;margin-bottom:15px">
      <p><strong>Trame vierge</strong> — Le test de fin de formation sera complété par le stagiaire à l'issue de la session.</p>
    </div>`;
    extra += tableHTML(["N°", "Question", "Options proposées", "Réponse du stagiaire", "Résultat"], rows);
    extra += `<div class="section"><p><strong>Score : ____ / ${qcm.length}  (____ %)</strong></p>
      <p><strong>Appréciation :</strong> ____________________________________________________________</p></div>`;
  } else {
    const score = correct;
    const pct = Math.round((score / qcm.length) * 100);
    const fullName = `${s.civilite ? s.civilite + " " : ""}${s.prenom} ${s.nom}`;
    const prenom = s.prenom;

    // Appréciation enrichie pour le test de DÉBUT
    const enrichedDebutAppreciation = (): string => {
      const parts: string[] = [];
      if (pct >= 80) {
        parts.push(`${fullName} obtient un score de ${score}/${qcm.length} (${pct}%), traduisant une <strong>excellente maîtrise initiale</strong> des prérequis liés à la formation « ${f.intitule} ».`);
        parts.push(`Les fondamentaux sont solidement acquis : ${prenom} identifie correctement les notions clés et mobilise un vocabulaire professionnel précis dès le démarrage du parcours.`);
        parts.push(`<strong>Recommandation pédagogique :</strong> orienter la progression vers les contenus de niveau avancé, approfondir les mises en situation complexes et valoriser l'autonomie sur les exercices pratiques.`);
      } else if (pct >= 60) {
        parts.push(`${fullName} obtient un score de ${score}/${qcm.length} (${pct}%), traduisant un <strong>bon niveau initial</strong> sur les fondamentaux de la formation « ${f.intitule} ».`);
        parts.push(`La majorité des notions de base sont maîtrisées. Quelques points techniques nécessitent un approfondissement, notamment sur les aspects méthodologiques et les procédures spécifiques au métier.`);
        parts.push(`<strong>Recommandation pédagogique :</strong> prévoir des rappels ciblés en début de parcours et renforcer les exercices d'application sur les notions partiellement acquises.`);
      } else if (pct >= 40) {
        parts.push(`${fullName} obtient un score de ${score}/${qcm.length} (${pct}%), traduisant un <strong>niveau intermédiaire</strong> à l'entrée en formation « ${f.intitule} ».`);
        parts.push(`Des bases existent mais restent fragiles. Plusieurs notions fondamentales doivent être consolidées avant d'aborder les contenus avancés. ${prenom} montre néanmoins une bonne réceptivité et une motivation à progresser.`);
        parts.push(`<strong>Recommandation pédagogique :</strong> mettre en place un <em>accompagnement renforcé</em> sur les modules 1 et 2, avec apports théoriques complémentaires et exercices de remédiation avant chaque évaluation intermédiaire.`);
      } else {
        parts.push(`${fullName} obtient un score de ${score}/${qcm.length} (${pct}%), traduisant un <strong>niveau débutant</strong> à l'entrée en formation « ${f.intitule} ».`);
        parts.push(`Les prérequis ne sont pas encore acquis. Un <em>apport théorique complet</em> sera nécessaire sur l'ensemble des blocs de compétences afin de sécuriser les apprentissages à venir.`);
        parts.push(`<strong>Recommandation pédagogique :</strong> individualiser le parcours avec un accompagnement pédagogique renforcé, multiplier les mises en pratique guidées et planifier un point d'étape à mi-parcours pour ajuster la progression.`);
      }
      return parts.map(p => `<p style="margin:6px 0">${p}</p>`).join("");
    };

    const niveau = isDebut
      ? (pct >= 70 ? "Bon niveau initial" : pct >= 40 ? "Niveau intermédiaire" : "Niveau débutant")
      : (pct >= 80 ? "Objectifs atteints — Excellent" : pct >= 60 ? "Objectifs atteints" : "Objectifs partiellement atteints");

    if (isDebut) {
      extra += tableHTML(["N°", "Question", "Options proposées", "Réponse du stagiaire", "Bonne réponse", "Résultat"], rows);
    } else {
      extra += tableHTML(["N°", "Question", "Réponse du stagiaire", "Bonne réponse", "Résultat"], rows);
    }
    extra += `<div class="section section-green"><p><strong>Score : ${score}/${qcm.length} (${pct}%)</strong> — <strong>Niveau :</strong> ${niveau}</p>
      <p><strong>Appréciation du formateur :</strong></p>
      ${isDebut ? enrichedDebutAppreciation() : `<p>${niveau}.</p>`}</div>`;
  }

  const sigDate = mode === "debut"
    ? formatDate(getStagiaireDateDebut(s, f))
    : (renderEmpty ? "" : formatDate(getStagiaireDateFin(s, f)));
  return buildDocument({
    org: o, title, subtitle: f.intitule, formation: f, showFormationInfo: false, stagiaires: [s], extraHtml: extra,
    signatures: { type: "2", labels: ["Le Stagiaire", "Le Formateur"], names: [`${s.prenom} ${s.nom}`, f.formateur], dates: sigDate ? [sigDate, sigDate] : undefined },
  });
}

function genAIExerciceIntermediaire(o: OrganismeInfo, f: FormationInfo, stagiaires: StagiaireInfo[], si: number): string {
  const pack: AIEvalPack | null = getCachedPack(f);
  const s = stagiaires[si] || stagiaires[0];
  if (!pack) return aiPackPlaceholder(o, f, "EXERCICE INTERMÉDIAIRE", s);
  const ex = pack.exerciceIntermediaire;

  // Date de l'exercice intermédiaire = jour médian de la formation du stagiaire
  const stagDays = getStagiaireDays(s, f);
  const midIdx = stagDays.length > 0 ? Math.floor(stagDays.length / 2) : -1;
  const dateExercice = midIdx >= 0 && stagDays[midIdx]
    ? stagDays[midIdx]
    : formatDate(getStagiaireDateDebut(s, f));

  let extra = `<h2>${ex.titre}</h2>`;
  extra += `<p><strong>Stagiaire :</strong> ${s.civilite ? s.civilite + " " : ""}${s.prenom} ${s.nom}<br>
    <strong>Formation :</strong> ${f.intitule}<br>
    <strong>Date de l'exercice :</strong> ${dateExercice} <em>(mi-parcours)</em></p>`;
  extra += `<div class="section"><p><strong>Mise en situation :</strong></p><p>${ex.contexte}</p></div>`;

  let totalObtained = 0;
  let totalMax = 0;
  ex.questions.forEach((q, qi) => {
    const note = noteForOpenQuestion(q.points, s, si, qi);
    totalObtained += note;
    totalMax += q.points;
    const studentAnswer = studentAnswerFromCorrection(q.reponseAttendue, s, si, qi);
    extra += `<div class="section" style="margin-top:15px"><p><strong>Question ${qi + 1} (${q.points} pts) :</strong> ${q.question}</p>
      <p style="background:#f8fafc;padding:10px;border-left:3px solid #3b82f6"><em>Réponse du stagiaire :</em><br>${studentAnswer.replace(/\n/g, "<br>")}</p>
      <p style="background:#f0fdf4;padding:10px;border-left:3px solid #16a34a"><em>Corrigé attendu :</em><br>${q.reponseAttendue}</p>
      <p><strong>Note attribuée : ${note}/${q.points}</strong></p></div>`;
  });

  const pct = Math.round((totalObtained / totalMax) * 100);
  extra += `<div class="section section-green"><p><strong>Note globale : ${totalObtained}/${totalMax} (${pct}%)</strong></p>
    <p><strong>Appréciation formateur :</strong> ${pct >= 80 ? "Excellente progression à mi-parcours." : pct >= 60 ? "Bonne progression, à confirmer en évaluation finale." : "Progression à consolider sur la 2e moitié de formation."}</p></div>`;

  return buildDocument({
    org: o, title: "EXERCICE INTERMÉDIAIRE — RÉSULTATS DÉTAILLÉS", subtitle: f.intitule, formation: f, showFormationInfo: false, stagiaires: [s], extraHtml: extra,
    signatures: { type: "2", labels: ["Le Stagiaire", "Le Formateur"], names: [`${s.prenom} ${s.nom}`, f.formateur] },
  });
}

function genAIEvaluationFinale(o: OrganismeInfo, f: FormationInfo, stagiaires: StagiaireInfo[], si: number): string {
  const pack: AIEvalPack | null = getCachedPack(f);
  const s = stagiaires[si] || stagiaires[0];
  if (!pack) return aiPackPlaceholder(o, f, "ÉVALUATION FINALE", s);
  const ev = pack.evaluationFinale;

  let extra = `<h2>${ev.titre}</h2>`;
  extra += `<p><strong>Stagiaire :</strong> ${s.civilite ? s.civilite + " " : ""}${s.prenom} ${s.nom}<br>
    <strong>Formation :</strong> ${f.intitule}<br>
    <strong>Date :</strong> ${formatDate(getStagiaireDateFin(s, f))}<br>
    <strong>Nombre d'exercices :</strong> ${ev.exercices.length}</p>`;

  let totalObtained = 0;
  let totalMax = 0;
  ev.exercices.forEach((exo, ei) => {
    const note = noteForOpenQuestion(exo.points, s, si, ei + 100);
    totalObtained += note;
    totalMax += exo.points;
    const studentAnswer = studentAnswerFromCorrection(exo.reponseAttendue, s, si, ei + 100);
    extra += `<div class="page-break"></div>`;
    extra += `<h3>Exercice ${ei + 1} : ${exo.titre} (${exo.points} pts)</h3>`;
    extra += `<div class="section"><p><strong>Consigne :</strong></p><p>${exo.consigne}</p></div>`;
    extra += `<div class="section" style="background:#f8fafc;border-left:3px solid #3b82f6"><p><strong>Production du stagiaire :</strong></p><p>${studentAnswer.replace(/\n/g, "<br>")}</p></div>`;
    extra += `<div class="section" style="background:#f0fdf4;border-left:3px solid #16a34a"><p><strong>Corrigé / Critères de réussite :</strong></p><p>${exo.reponseAttendue}</p></div>`;
    extra += `<p><strong>Note attribuée : ${note}/${exo.points}</strong> — ${note >= exo.points * 0.9 ? "Excellent" : note >= exo.points * 0.75 ? "Très satisfaisant" : "Satisfaisant"}</p>`;
  });

  const pct = Math.round((totalObtained / totalMax) * 100);
  const valide = pct >= 60;
  extra += `<div class="page-break"></div>`;
  extra += `<div class="section section-green"><h3>Synthèse de l'évaluation finale</h3>
    <p><strong>Note globale : ${totalObtained}/${totalMax} (${pct}%)</strong></p>
    <p><strong>Résultat : ${valide ? "VALIDÉ" : "À REPRENDRE"}</strong></p>
    <p><strong>Appréciation du formateur :</strong> ${valide ? `${s.prenom} ${s.nom} a démontré une bonne maîtrise des compétences attendues à l'issue de la formation « ${f.intitule} ». Les objectifs pédagogiques sont atteints.` : "Acquis partiels, un complément de formation est recommandé."}</p>
  </div>`;

  return buildDocument({
    org: o, title: "ÉVALUATION FINALE — RÉSULTATS DÉTAILLÉS", subtitle: f.intitule, formation: f, showFormationInfo: false, stagiaires: [s], extraHtml: extra,
    signatures: { type: "2", labels: ["Le Stagiaire", "Le Formateur"], names: [`${s.prenom} ${s.nom}`, f.formateur] },
  });
}

/**
 * Exercices par jour pour un stagiaire :
 * un exercice par journée de formation (selon les jours effectifs du stagiaire),
 * avec énoncé, production stagiaire et corrigé — varié d'un stagiaire à l'autre.
 * Pour les jours futurs (formation non encore passée), l'exercice reste en trame à compléter.
 */
function genAIExercicesParJour(o: OrganismeInfo, f: FormationInfo, stagiaires: StagiaireInfo[], si: number, onlyDayIdx?: number): string {
  const pack: AIEvalPack | null = getCachedPack(f);
  const s = stagiaires[si] || stagiaires[0];
  const days = getStagiaireDays(s, f);
  const singleDay = typeof onlyDayIdx === "number" && onlyDayIdx >= 0 && onlyDayIdx < days.length;
  const title = singleDay
    ? `EXERCICE — JOUR ${onlyDayIdx! + 1}`
    : "EXERCICES QUOTIDIENS — UN EXERCICE PAR JOUR";

  if (!pack) return aiPackPlaceholder(o, f, title, s);

  // ----- Pool d'items mixtes (QCM + exercices ouverts) -----
  type Item =
    | { kind: "qcm"; titre: string; question: string; options: string[]; correctIndex: number; points: number }
    | { kind: "open"; titre: string; consigne: string; reponseAttendue: string; points: number };

  const pool: Item[] = [];

  // QCM (1 point chacun) - on prend début + fin pour varier
  [...(pack.qcmDebut || []), ...(pack.qcmFin || [])].forEach((q, i) => {
    pool.push({
      kind: "qcm",
      titre: `QCM ${i + 1}`,
      question: q.question,
      options: q.options,
      correctIndex: q.correctIndex,
      points: 1,
    });
  });

  // Questions ouvertes de l'exercice intermédiaire
  pack.exerciceIntermediaire.questions.forEach((q, i) => {
    pool.push({
      kind: "open",
      titre: `Exercice ${i + 1} — ${pack.exerciceIntermediaire.titre}`,
      consigne: q.question,
      reponseAttendue: q.reponseAttendue,
      points: q.points,
    });
  });

  // Exercices pratiques de l'évaluation finale
  pack.evaluationFinale.exercices.forEach((exo) => {
    pool.push({ kind: "open", titre: exo.titre, consigne: exo.consigne, reponseAttendue: exo.reponseAttendue, points: exo.points });
  });

  if (pool.length === 0) return aiPackPlaceholder(o, f, title, s);

  // Séparation pour pouvoir alterner QCM/Ouvert
  const qcmPool = pool.filter((p) => p.kind === "qcm");
  const openPool = pool.filter((p) => p.kind === "open");

  // Décalage déterministe par stagiaire
  const seedBase = ((s?.prenom || "").length * 17 + (s?.nom || "").length * 31 + si * 7);

  let extra = `<h2>${title}</h2>`;
  extra += `<p><strong>Stagiaire :</strong> ${s.civilite ? s.civilite + " " : ""}${s.prenom} ${s.nom}<br>
    <strong>Formation :</strong> ${f.intitule}<br>
    <strong>Période :</strong> du ${formatDate(getStagiaireDateDebut(s, f))} au ${formatDate(getStagiaireDateFin(s, f))}<br>
    ${singleDay ? `<strong>Jour :</strong> ${onlyDayIdx! + 1} sur ${days.length}` : `<strong>Nombre d'exercices :</strong> ${days.length} (1 par journée de formation, notes croissantes traduisant la progression)`}</p>`;

  // Banques pour les "blocs jour"
  const qcmBank = [...(pack.qcmDebut || []), ...(pack.qcmFin || [])];
  const openBank = [
    ...pack.exerciceIntermediaire.questions.map((q, i) => ({
      titre: `${pack.exerciceIntermediaire.titre} — Question ${i + 1}`,
      consigne: q.question,
      reponseAttendue: q.reponseAttendue,
      points: q.points,
    })),
    ...pack.evaluationFinale.exercices.map((e) => ({
      titre: e.titre, consigne: e.consigne, reponseAttendue: e.reponseAttendue, points: e.points,
    })),
  ];

  let totalObtained = 0;
  let totalMax = 0;
  let scoredCount = 0;

  days.forEach((day, di) => {
    if (singleDay && di !== onlyDayIdx) return;
    const past = isFrLongDayPast(day);
    const t = days.length <= 1 ? 1 : di / (days.length - 1);
    const quality = 0.55 + t * 0.4;
    const useQCM = (di % 2 === 0) && qcmBank.length > 0;

    // Saut de page entre chaque jour (sauf le 1er) — uniquement en mode global
    if (!singleDay && di > 0) extra += `<div class="page-break" style="page-break-before:always"></div>`;

    extra += `<div class="day-block" style="border:1px solid #cbd5e1;padding:14px;margin-top:10px">
      <h3 style="margin:0 0 8px 0;color:#1e40af">Jour ${di + 1} sur ${days.length} — ${day}</h3>
      <p style="margin:0 0 10px 0;color:#475569"><strong>Type d'évaluation :</strong> ${useQCM ? "QCM (10 questions)" : "Exercice pratique (4 questions ouvertes)"}</p>`;

    if (useQCM) {
      // Sélection de 10 QCM décalés selon stagiaire+jour
      const qcmCount = Math.min(10, qcmBank.length);
      const offset = (seedBase + di * 13) % qcmBank.length;
      const selected = Array.from({ length: qcmCount }, (_, k) => qcmBank[(offset + k) % qcmBank.length]);

      // Cible de bonnes réponses croissante avec les jours : 5 → 10
      const targetCorrect = Math.max(4, Math.min(qcmCount, Math.round(5 + t * 5)));
      const wrongCount = qcmCount - targetCorrect;
      const wrongSet = new Set<number>();
      let k = 0;
      while (wrongSet.size < wrongCount && k < qcmCount * 6) {
        wrongSet.add((seedBase + di * 7 + k * 11) % qcmCount);
        k++;
      }

      let dayObtained = 0;
      const rows: string[] = [];
      selected.forEach((q, qi) => {
        const correct = !wrongSet.has(qi);
        const chosenIdx = correct ? q.correctIndex : [0, 1, 2, 3].filter((x) => x !== q.correctIndex)[(seedBase + di + qi) % 3];
        if (past && correct) dayObtained++;

        rows.push(`
          <div style="margin:8px 0;padding:8px;border-left:3px solid ${correct ? "#16a34a" : "#dc2626"};background:#f8fafc">
            <p style="margin:0 0 4px 0"><strong>Q${qi + 1}.</strong> ${q.question}</p>
            <ul style="margin:4px 0 6px 22px;padding:0">
              ${q.options.map((opt, oi) => {
                const isChosen = past && oi === chosenIdx;
                const isRight = oi === q.correctIndex;
                return `<li style="${isChosen ? "font-weight:700" : ""}${isRight ? ";color:#15803d" : ""}">
                  ${isChosen ? "☒" : "☐"} ${String.fromCharCode(65 + oi)}. ${opt}${isRight ? " <em style='color:#15803d'>(bonne réponse)</em>" : ""}
                </li>`;
              }).join("")}
            </ul>
            ${past ? `<p style="margin:4px 0 0 0;font-size:0.9em"><em>Réponse stagiaire :</em> ${String.fromCharCode(65 + chosenIdx)} — ${correct ? "<span style='color:#15803d'>Correcte ✓</span>" : "<span style='color:#dc2626'>Incorrecte ✗</span>"}</p>` : `<p style="margin:4px 0 0 0;font-size:0.9em;color:#92400e"><em>Réponse à compléter le jour J</em></p>`}
          </div>`);
      });
      extra += rows.join("");

      if (past) {
        totalObtained += dayObtained;
        totalMax += qcmCount;
        scoredCount++;
        extra += `<p style="margin-top:10px;padding:8px;background:#ecfdf5;border-left:3px solid #16a34a"><strong>Score du jour : ${dayObtained}/${qcmCount}</strong></p>`;
      } else {
        extra += `<p style="margin-top:10px;padding:8px;background:#fef3c7;border-left:3px solid #f59e0b"><strong>Score : ___ / ${qcmCount}</strong></p>`;
      }
    } else {
      // Exercice pratique : 4 questions ouvertes
      const exoCount = 4;
      const offset = (seedBase + di * 17) % Math.max(openBank.length, 1);
      const selected = Array.from({ length: Math.min(exoCount, openBank.length) }, (_, k) => openBank[(offset + k) % openBank.length]);

      let dayObtained = 0;
      let dayMax = 0;
      selected.forEach((exo, ei) => {
        dayMax += exo.points;
        extra += `<div style="margin:8px 0;padding:8px;border-left:3px solid #3b82f6;background:#f8fafc">
          <p style="margin:0 0 4px 0"><strong>Exercice ${ei + 1} — ${exo.titre}</strong> (${exo.points} pts)</p>
          <p style="margin:4px 0"><em>Consigne :</em> ${exo.consigne}</p>`;
        if (past) {
          const note = noteForDayProgression(exo.points, di, days.length, s, si);
          dayObtained += note;
          const answer = humanizedStudentAnswer(exo.reponseAttendue, s, si, di * 10 + ei, quality);
          const feedback = humanizedTeacherFeedback(note, exo.points, s, si, di * 10 + ei);
          extra += `<p style="margin:6px 0;padding:6px;background:#fff;border-left:2px solid #64748b"><em>Production stagiaire :</em><br>${answer.replace(/\n/g, "<br>")}</p>
            <p style="margin:6px 0;padding:6px;background:#f0fdf4;border-left:2px solid #16a34a"><em>Corrigé attendu :</em><br>${exo.reponseAttendue}</p>
            <p style="margin:4px 0 0 0"><strong>Note : ${note}/${exo.points}</strong> — <em>${feedback}</em></p>`;
        } else {
          extra += `<p style="margin:6px 0;padding:6px;background:#fef3c7;border-left:2px solid #f59e0b"><em>Production stagiaire :</em> _____________________ <em>(à compléter)</em></p>
            <p style="margin:6px 0;padding:6px;background:#f0fdf4;border-left:2px solid #16a34a"><em>Corrigé attendu :</em><br>${exo.reponseAttendue}</p>
            <p style="margin:4px 0 0 0"><strong>Note : ___ / ${exo.points}</strong></p>`;
        }
        extra += `</div>`;
      });

      if (past) {
        totalObtained += dayObtained;
        totalMax += dayMax;
        scoredCount++;
        extra += `<p style="margin-top:10px;padding:8px;background:#ecfdf5;border-left:3px solid #16a34a"><strong>Score du jour : ${dayObtained}/${dayMax}</strong></p>`;
      } else {
        extra += `<p style="margin-top:10px;padding:8px;background:#fef3c7;border-left:3px solid #f59e0b"><strong>Score : ___ / ${dayMax}</strong></p>`;
      }
    }

    extra += `</div>`;
  });

  if (scoredCount > 0 && !singleDay) {
    extra += `<div class="page-break" style="page-break-before:always"></div>`;
    const pct = Math.round((totalObtained / totalMax) * 100);
    extra += `<div class="section section-green" style="margin-top:20px">
      <h3>Synthèse globale</h3>
      <p><strong>Note cumulée :</strong> ${totalObtained}/${totalMax} (${pct}%)</p>
      <p><strong>Progression :</strong> Notes en hausse continue tout au long de la formation, traduisant la montée en compétence du stagiaire.</p>
      <p><strong>Appréciation formateur :</strong> ${pct >= 80 ? "Très bonne régularité et progression sur l'ensemble des journées." : pct >= 60 ? "Progression satisfaisante, à consolider sur les notions les plus techniques." : "Acquis partiels — un accompagnement renforcé est recommandé."}</p>
    </div>`;
  }

  return buildDocument({
    org: o, title, subtitle: f.intitule, formation: f, showFormationInfo: false, stagiaires: [s], extraHtml: extra,
    signatures: { type: "2", labels: ["Le Stagiaire", "Le Formateur"], names: [`${s.prenom} ${s.nom}`, f.formateur] },
  });
}

/**
 * Exercices par module pour la formation Gestionnaire de paie.
 * 6 modules × (5 QCM + 1 exercice pratique) — humanisé et différent par stagiaire.
 */
function genPaieExerciceModule(o: OrganismeInfo, f: FormationInfo, stagiaires: StagiaireInfo[], si: number, mi: number): string {
  const modules = getModuleExercisesFor(f);
  const s = stagiaires[si] || stagiaires[0];
  const mod = modules[mi];
  const seedBase = ((s?.prenom || "").length * 17 + (s?.nom || "").length * 31 + si * 7);
  const progress = modules.length <= 1 ? 1 : mi / (modules.length - 1);
  const quality = 0.60 + progress * 0.35;

  let extra = `<h2>${mod.moduleTitre}</h2>`;
  extra += `<p><strong>Stagiaire :</strong> ${s.civilite ? s.civilite + " " : ""}${s.prenom} ${s.nom}<br>
    <strong>Formation :</strong> ${f.intitule}<br>
    <strong>Période :</strong> du ${formatDate(getStagiaireDateDebut(s, f))} au ${formatDate(getStagiaireDateFin(s, f))}<br>
    <strong>Format :</strong> 5 QCM ciblés + 1 exercice pratique corrigé</p>`;

  // QCM
  const targetCorrect = Math.max(3, Math.min(5, Math.round(3 + progress * 2)));
  const wrongCount = mod.qcm.length - targetCorrect;
  const wrongSet = new Set<number>();
  let k = 0;
  while (wrongSet.size < wrongCount && k < mod.qcm.length * 6) {
    wrongSet.add((seedBase + mi * 7 + k * 11) % mod.qcm.length);
    k++;
  }
  let qcmObtained = 0;
  extra += `<h3 style="color:#1e40af">QCM du module (5 questions)</h3>`;
  mod.qcm.forEach((q, qi) => {
    const correct = !wrongSet.has(qi);
    const chosenIdx = correct
      ? q.correctIndex
      : [0, 1, 2, 3].filter((x) => x !== q.correctIndex)[(seedBase + mi + qi) % 3];
    if (correct) qcmObtained++;
    const options = q.options.map((opt, oi) => {
      const isChosen = oi === chosenIdx;
      const isRight = oi === q.correctIndex;
      return `<li style="${isChosen ? "font-weight:700" : ""}${isRight ? ";color:#15803d" : ""}">
        ${isChosen ? "☒" : "☐"} ${String.fromCharCode(65 + oi)}. ${opt}${isRight ? " <em style='color:#15803d'>(bonne réponse)</em>" : ""}
      </li>`;
    }).join("");
    extra += `<div style="margin:6px 0;padding:8px;border-left:3px solid ${correct ? "#16a34a" : "#dc2626"};background:#f8fafc">
      <p style="margin:0 0 4px 0"><strong>Q${qi + 1}.</strong> ${q.question}</p>
      <ul style="margin:4px 0 6px 22px;padding:0">${options}</ul>
      <p style="margin:4px 0 0 0;font-size:0.9em"><em>Réponse stagiaire :</em> ${String.fromCharCode(65 + chosenIdx)} — ${correct ? "<span style='color:#15803d'>Correcte ✓</span>" : "<span style='color:#dc2626'>Incorrecte ✗</span>"}</p>

    </div>`;
  });
  extra += `<p style="padding:8px;background:#ecfdf5;border-left:3px solid #16a34a"><strong>Score QCM : ${qcmObtained}/${mod.qcm.length}</strong></p>`;

  // Exercice pratique
  const exo = mod.exercice;
  const note = noteForDayProgression(exo.points, mi, modules.length, s, si);
  const answer = pickExoProduction(exo, s, si, mi, quality);
  const feedback = humanizedTeacherFeedback(note, exo.points, s, si, mi * 13 + 3);
  extra += `<h3 style="color:#1e40af">Exercice pratique — ${exo.titre} (${exo.points} pts)</h3>
    <div style="padding:10px;border-left:3px solid #3b82f6;background:#f8fafc">
      <p><em>Consigne :</em> ${exo.consigne}</p>
      <p style="padding:6px;background:#fff;border-left:2px solid #64748b"><em>Production stagiaire :</em><br>${answer.replace(/\n/g, "<br>")}</p>
      <p style="padding:6px;background:#f0fdf4;border-left:2px solid #16a34a"><em>Corrigé attendu :</em><br>${exo.reponseAttendue}</p>
      <p><strong>Note : ${note}/${exo.points}</strong> — <em>${feedback}</em></p>
    </div>`;

  const modObt = qcmObtained + note;
  const modMax = mod.qcm.length + exo.points;
  extra += `<p style="margin-top:12px;padding:8px;background:#dbeafe;border-left:3px solid #1e40af"><strong>Score total du module : ${modObt}/${modMax}</strong></p>`;

  return buildDocument({
    org: o, title: `EXERCICES — ${mod.moduleTitre}`, subtitle: `${s.prenom} ${s.nom} – ${f.intitule}`, formation: f, showFormationInfo: false, stagiaires: [s], extraHtml: extra,
  });

}

function genPaieExercicesParModule(o: OrganismeInfo, f: FormationInfo, stagiaires: StagiaireInfo[], si: number): string {
  const modules = getModuleExercisesFor(f);

  const s = stagiaires[si] || stagiaires[0];
  const seedBase = ((s?.prenom || "").length * 17 + (s?.nom || "").length * 31 + si * 7);

  let extra = `<h2>EXERCICES PAR MODULE — RÉSULTATS DÉTAILLÉS</h2>`;
  extra += `<p><strong>Stagiaire :</strong> ${s.civilite ? s.civilite + " " : ""}${s.prenom} ${s.nom}<br>
    <strong>Formation :</strong> ${f.intitule}<br>
    <strong>Période :</strong> du ${formatDate(getStagiaireDateDebut(s, f))} au ${formatDate(getStagiaireDateFin(s, f))}<br>
    <strong>Nombre de modules évalués :</strong> ${modules.length} (5 QCM + 1 exercice pratique par module)</p>`;

  let grandObtained = 0;
  let grandMax = 0;

  modules.forEach((mod, mi) => {
    if (mi > 0) extra += `<div class="page-break" style="page-break-before:always"></div>`;

    // Progression : notes en hausse à travers les modules
    const progress = modules.length <= 1 ? 1 : mi / (modules.length - 1);
    const quality = 0.60 + progress * 0.35; // 0.60 → 0.95

    extra += `<div style="border:1px solid #cbd5e1;padding:14px;margin-top:10px">
      <h3 style="margin:0 0 10px 0;color:#1e40af">${mod.moduleTitre}</h3>`;

    // ---- QCM (5 questions) ----
    const targetCorrect = Math.max(3, Math.min(5, Math.round(3 + progress * 2))); // 3 → 5
    const wrongCount = mod.qcm.length - targetCorrect;
    const wrongSet = new Set<number>();
    let k = 0;
    while (wrongSet.size < wrongCount && k < mod.qcm.length * 6) {
      wrongSet.add((seedBase + mi * 7 + k * 11) % mod.qcm.length);
      k++;
    }

    let qcmObtained = 0;
    extra += `<h4 style="color:#1e40af;margin:10px 0 6px 0">QCM du module (5 questions)</h4>`;
    mod.qcm.forEach((q, qi) => {
      const correct = !wrongSet.has(qi);
      const chosenIdx = correct
        ? q.correctIndex
        : [0, 1, 2, 3].filter((x) => x !== q.correctIndex)[(seedBase + mi + qi) % 3];
      if (correct) qcmObtained++;

      const options = q.options.map((opt, oi) => {
        const isChosen = oi === chosenIdx;
        const isRight = oi === q.correctIndex;
        return `<li style="${isChosen ? "font-weight:700" : ""}${isRight ? ";color:#15803d" : ""}">
          ${isChosen ? "☒" : "☐"} ${String.fromCharCode(65 + oi)}. ${opt}${isRight ? " <em style='color:#15803d'>(bonne réponse)</em>" : ""}
        </li>`;
      }).join("");

      extra += `<div style="margin:6px 0;padding:8px;border-left:3px solid ${correct ? "#16a34a" : "#dc2626"};background:#f8fafc">
        <p style="margin:0 0 4px 0"><strong>Q${qi + 1}.</strong> ${q.question}</p>
        <ul style="margin:4px 0 6px 22px;padding:0">${options}</ul>
        <p style="margin:4px 0 0 0;font-size:0.9em"><em>Réponse stagiaire :</em> ${String.fromCharCode(65 + chosenIdx)} — ${correct ? "<span style='color:#15803d'>Correcte ✓</span>" : "<span style='color:#dc2626'>Incorrecte ✗</span>"}</p>
      </div>`;
    });
    extra += `<p style="margin:8px 0;padding:8px;background:#ecfdf5;border-left:3px solid #16a34a"><strong>Score QCM : ${qcmObtained}/${mod.qcm.length}</strong></p>`;

    // ---- Exercice pratique (1) ----
    const exo = mod.exercice;
    const note = noteForDayProgression(exo.points, mi, modules.length, s, si);
    const answer = pickExoProduction(exo, s, si, mi, quality);
    const feedback = humanizedTeacherFeedback(note, exo.points, s, si, mi * 13 + 3);
    extra += `<h4 style="color:#1e40af;margin:14px 0 6px 0">Exercice pratique — ${exo.titre} (${exo.points} pts)</h4>
      <div style="margin:6px 0;padding:10px;border-left:3px solid #3b82f6;background:#f8fafc">
        <p style="margin:0 0 6px 0"><em>Consigne :</em> ${exo.consigne}</p>
        <p style="margin:6px 0;padding:6px;background:#fff;border-left:2px solid #64748b"><em>Production stagiaire :</em><br>${answer.replace(/\n/g, "<br>")}</p>
        <p style="margin:6px 0;padding:6px;background:#f0fdf4;border-left:2px solid #16a34a"><em>Corrigé attendu :</em><br>${exo.reponseAttendue}</p>
        <p style="margin:6px 0 0 0"><strong>Note : ${note}/${exo.points}</strong> — <em>${feedback}</em></p>
      </div>`;

    const modObt = qcmObtained + note;
    const modMax = mod.qcm.length + exo.points;
    grandObtained += modObt;
    grandMax += modMax;
    extra += `<p style="margin-top:10px;padding:8px;background:#dbeafe;border-left:3px solid #1e40af"><strong>Score du module ${mi + 1} : ${modObt}/${modMax}</strong></p>`;
    extra += `</div>`;
  });

  // ---- Synthèse globale ----
  extra += `<div class="page-break" style="page-break-before:always"></div>`;
  const pct = grandMax > 0 ? Math.round((grandObtained / grandMax) * 100) : 0;
  extra += `<div class="section section-green" style="margin-top:20px">
    <h3>Synthèse globale des exercices par module</h3>
    <p><strong>Note cumulée :</strong> ${grandObtained}/${grandMax} (${pct}%)</p>
    <p><strong>Progression :</strong> Résultats en hausse module après module, cohérents avec la montée en compétences attendue sur la paie (fondamentaux → bulletin → cotisations/DSN → absences → rupture → contrôles).</p>
    <p><strong>Appréciation formateur :</strong> ${pct >= 80 ? `${s.prenom} ${s.nom} a démontré une très bonne maîtrise de l'ensemble des blocs de la fonction paie.` : pct >= 60 ? "Progression satisfaisante, à consolider sur les modules les plus techniques (cotisations, DSN)." : "Acquis partiels — accompagnement renforcé recommandé sur les modules 3 et 4."}</p>
  </div>`;

  return buildDocument({
    org: o, title: "EXERCICES PAR MODULE — RÉSULTATS DÉTAILLÉS", subtitle: f.intitule, formation: f, showFormationInfo: false, stagiaires: [s], extraHtml: extra,
  });

}
